import{_ as e,c as i,o as l,a2 as a}from"./chunks/framework.Dg5ihhEM.js";const p=JSON.parse('{"title":"Code Review","description":"","frontmatter":{},"headers":[],"relativePath":"codeReview/index.md","filePath":"codeReview/index.md"}'),o={name:"codeReview/index.md"},t=a('<h1 id="code-review" tabindex="-1">Code Review <a class="header-anchor" href="#code-review" aria-label="Permalink to &quot;Code Review&quot;">​</a></h1><blockquote><p>原文: <a href="https://github.com/google/eng-practices/blob/master/review/reviewer/looking-for.md" target="_blank" rel="noreferrer">https://github.com/google/eng-practices/blob/master/review/reviewer/looking-for.md</a></p></blockquote><h2 id="codereview时-我们需要review哪些些内容" tabindex="-1">CodeReview时,我们需要Review哪些些内容? <a class="header-anchor" href="#codereview时-我们需要review哪些些内容" aria-label="Permalink to &quot;CodeReview时,我们需要Review哪些些内容?&quot;">​</a></h2><h3 id="design-设计" tabindex="-1">Design(设计) <a class="header-anchor" href="#design-设计" aria-label="Permalink to &quot;Design(设计)&quot;">​</a></h3><p>最重要的内容,应该是 Change List, 即当前PR提交的代码,所修改的点,以及它的架构设计原理等.</p><ul><li>它所修改的各代码段是否有意义?</li><li>它与其他子系统是否能够良好的集成?</li><li>现在添加这个新功能, 是最好的时机吗?</li><li>...</li></ul><h3 id="functionality-功能性" tabindex="-1">Functionality(功能性) <a class="header-anchor" href="#functionality-功能性" aria-label="Permalink to &quot;Functionality(功能性)&quot;">​</a></h3><ul><li>这个CL是否达到了开发者的预期?</li><li>这段代码的目的, 对用户来说,有什么好处? <ul><li>用户, 即是最终用户, 也可以是其他开发人员</li></ul></li><li>是否已通过 eslint 检测?</li><li>已通过 unit test?</li><li>有没有其他边界没有考虑到? <ul><li>边界问题?</li><li>并发问题?</li></ul></li><li>核心的功能 或 影响较大的功能, 开发者能否演示这代码修改的点? 以供 代码审阅者 理解代码的影响(特别是UI交互的影响)</li></ul><h3 id="complexity-复杂度" tabindex="-1">Complexity(复杂度) <a class="header-anchor" href="#complexity-复杂度" aria-label="Permalink to &quot;Complexity(复杂度)&quot;">​</a></h3><blockquote><p>太复杂: 即代码阅读者很难快速阅读代码,理解代码的含义. 同时, 也意味着,开发人员在尝试调用或修改这些代码时,可能会引入错误.</p></blockquote><ul><li>CL中的功能实现,是否必须要这么复杂? <ul><li>单行代码是否太复杂?</li><li>函数是否太复杂?</li></ul></li><li>一些特殊场景的功能过于复杂,很有可能是过度设计(例如下面的场景). 代码审阅者应对过度设计特别警惕,鼓励开发人员解决当前所需要解决的问题, 而不是推测将来可能需要解决的问题. <ul><li>代码功能过于通用?</li><li>添加了系统当前不需要的功能?</li></ul></li></ul><h3 id="testing-测试" tabindex="-1">Testing(测试) <a class="header-anchor" href="#testing-测试" aria-label="Permalink to &quot;Testing(测试)&quot;">​</a></h3><p>根据CL, 添加 单元测试/端到端测试.</p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="https://github.com/google/eng-practices/blob/master/review/reviewer/looking-for.md" target="_blank" rel="noreferrer">Google: What to look for in a code review</a></li></ul>',15),r=[t];function n(c,d,s,h,u,b){return l(),i("div",null,r)}const _=e(o,[["render",n]]);export{p as __pageData,_ as default};
